#!/usr/bin/env python3
"""Write sync/ids.js, the puzzle-id grammar of tools/series.py as JavaScript.

    python3 tools/gen_ids_js.py          # rewrite sync/ids.js

The sync worker cannot import Python, so it gets the grammar as a generated
module; tests/test_ids_js.py fails when the file is stale."""
import json
import pathlib
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import series

OUT = pathlib.Path(__file__).resolve().parent.parent / "sync" / "ids.js"


def render():
    return (
        "// Generated by tools/gen_ids_js.py from tools/series.py. Do not edit.\n"
        f"export const ID_SERIES = {json.dumps(series.ID_SERIES)};\n"
        f"export const ID_NUMBER = {json.dumps(series.ID_NUMBER)};\n"
        f"export const ID_CLUE = {json.dumps(series.ID_CLUE)};\n"
        "export const PUZZLE_ID = `${ID_SERIES}-${ID_NUMBER}`;\n"
        "export const PUZZLE_ID_RE = new RegExp(`^${PUZZLE_ID}$`);\n"
        "export const VOTE_TARGET_RE = new RegExp(\n"
        "  `^(?:c:${PUZZLE_ID}:${ID_CLUE}|p:${PUZZLE_ID})$`);\n"
    )


if __name__ == "__main__":
    OUT.write_text(render())
